INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine automatisierte Sicherung immer schneller als eine manuelle?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Konfiguration und Datenmenge ab"}, {"text": "Ja", "correct": false, "because": "Automatisierung priorisiert Regelmäßigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist für mich bei der Automatisierung von Backups entscheidend?', 3, '[{"text": "Zeitplanung", "correct": true, "because": "Sichert regelmäßige Ausführung"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Nur Geschwindigkeit"}, {"text": "Manuelle Bestätigung", "correct": false, "because": "Widerspricht Automatisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten brauche ich für eine automatisierte Sicherung?', 5, '[{"text": "Skripte", "correct": true, "because": "Steuern Ablauf"}, {"text": "Zeitsteuerung", "correct": true, "because": "Definiert Intervalle"}, {"text": "Grafische Oberfläche", "correct": false, "because": "Optional"}, {"text": "Manuelle Eingriffe", "correct": false, "because": "Nicht automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Automatisierung reduziert Fehler. b) Sie ersetzt Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests bleiben nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Automatisierung eines Backup-Prozesses?', 4, '[{"text": "Zeitplan", "correct": false, "because": "Kern der Automatisierung"}, {"text": "Fehlerprotokolle", "correct": false, "because": "Wichtig für Überwachung"}, {"text": "Farbauswahl der GUI", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein automatisiertes System auch inkrementell sein kann?', 2, '[{"text": "Ja", "correct": true, "because": "Nur Änderungen sichern"}, {"text": "Nein", "correct": false, "because": "Nicht auf Vollbackups beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich für zeitgesteuerte Sicherungen?', 3, '[{"text": "Cron", "correct": true, "because": "Planung auf Unix-Systemen"}, {"text": "Excel", "correct": false, "because": "Kein Automatisierungstool"}, {"text": "Notepad", "correct": false, "because": "Nur Textbearbeitung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet mir eine automatisierte Lösung?', 5, '[{"text": "Konsistenz", "correct": true, "because": "Regelmäßige Ausführung"}, {"text": "Weniger manuelle Arbeit", "correct": true, "because": "Zeitersparnis"}, {"text": "Schnellere Datenübertragung", "correct": false, "because": "Hardwareabhängig"}, {"text": "Bessere Datenkompression", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Automatisierung spart Zeit. b) Sie macht Backups fehlerfrei. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehler möglich bei falscher Konfiguration"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine automatisierte Sicherung?', 4, '[{"text": "Zeitste olhouung", "correct": false, "because": "Definiert Ausführung"}, {"text": "Skript", "correct": false, "because": "Steuert Prozess"}, {"text": "Tägliche manuelle Checks", "correct": true, "because": "Widerspricht Automatisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind automatisierte Prozesse immer teurer?', 2, '[{"text": "Nein", "correct": true, "because": "Langfristig oft günstiger"}, {"text": "Ja", "correct": false, "because": "Kostenersparnis durch Effizienz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Automatisierung effektiv?', 4, '[{"text": "Regelmäßige Ausführung", "correct": true, "because": "Sichert Datenkontinuität"}, {"text": "Fehlerüberwachung", "correct": true, "because": "Erkennt Probleme früh"}, {"text": "Manuelle Eingriffe", "correct": false, "because": "Widerspricht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Automatisierung nur für große Datenmengen lohnt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Systeme profitieren"}, {"text": "Ja", "correct": false, "because": "Vorteile unabhängig von Größe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem automatisierten System?', 3, '[{"text": "Zuverlässigkeit", "correct": true, "because": "Sichert Funktion ohne Eingriff"}, {"text": "Schnelle Einrichtung", "correct": false, "because": "Qualität zählt mehr"}, {"text": "Minimale Kosten", "correct": false, "because": "Zuverlässigkeit wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Automatisierung braucht Skripte. b) Sie funktioniert nur mit Cloud.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Cloud optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Optionen verbessern eine automatisierte Sicherung?', 5, '[{"text": "Protokollierung", "correct": true, "because": "Nachverfolgbarkeit"}, {"text": "Alerts bei Fehlern", "correct": true, "because": "Schnelle Reaktion"}, {"text": "Manuelle Bestätigung", "correct": false, "because": "Nicht automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem automatisierten Prozess unwichtig?', 3, '[{"text": "Zeitplan", "correct": false, "because": "Definiert Ausführung"}, {"text": "Fehlerlogs", "correct": false, "because": "Wichtig für Diagnose"}, {"text": "Farbliche Markierung", "correct": true, "because": "Kein funktionaler Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ich Automatisierung auch lokal nutzen?', 3, '[{"text": "Ja", "correct": true, "because": "Unabhängig von Cloud"}, {"text": "Nein", "correct": false, "because": "Nicht auf Cloud beschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Automatisierung Tests überflüssig macht?', 2, '[{"text": "Nein", "correct": true, "because": "Tests sichern Qualität"}, {"text": "Ja", "correct": false, "because": "Automatisierung ergänzt Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für regelmäßige Sicherungen?', 4, '[{"text": "Task Scheduler", "correct": true, "because": "Windows-Zeitsteuerung"}, {"text": "Manuelle Ausführung", "correct": false, "because": "Nicht automatisiert"}, {"text": "Browser-Plug-in", "correct": false, "because": "Kein Backup-Tool"}]');
